# Michigan Interstate segments with the year each opened to traffic as a freeway
# (regardless of the route number signed at the time).
# Points are (lat, lon). approx=True means the source gives no exact date for this piece.
# Sources: michiganhighways.org route listings; Wikipedia route articles.

S = []
def seg(route, frm, to, a, b, year, note="", approx=False):
    S.append(dict(route=route, frm=frm, to=to, a=a, b=b, year=year, note=note, approx=approx))

